corporate_design.toad_component_blueprint:
canvas {
  size: 920px 580px;
  fill: #080612;
  font-family: "Orbitron, sans-serif";
}

>magenta = #FF007F;
>cyan = #00F0FF;
>white = #FFFFFF;

rect #arenaCard {
  at: center of canvas;
  size: 820px 480px;
  fill: #120C24;
  stroke: >magenta;
  stroke-width: 2px;
  radius: 8px;
}

text #arenaHeader {
  at: top left of #arenaCard offset 36px 36px;
  content: "PULSAR ARENA // PRO LEAGUE TOURNAMENT";
  font-size: 14px;
  font-weight: 800;
  color: >cyan;
}

text #arenaTitle {
  at: below #arenaHeader offset 16px;
  content: "GLOBAL FINALS: € 100.000 PRIZE POOL";
  font-size: 32px;
  font-weight: 800;
  color: >white;
}
